import { Given, Then, When } from '@cucumber/cucumber';
import { renderToStaticMarkup } from 'react-dom/server';

import { StatusBadge } from '../../status-badge.js';
import type { StatusBadgeProps } from '../../status-badge.js';

type StatusBadgeTone = NonNullable<StatusBadgeProps['tone']>;

interface BadgeScenario {
  badge: StatusBadgeProps;
  markup?: string;
}

const scenarios = new WeakMap<object, BadgeScenario>();

function toneFrom(value: string): StatusBadgeTone {
  if (value === 'neutral' || value === 'positive' || value === 'warning' || value === 'critical') {
    return value;
  }

  throw new Error(`The scenario supplied an unsupported badge tone: ${value}`);
}

function scenarioFor(world: object): BadgeScenario {
  const scenario = scenarios.get(world);

  if (!scenario) {
    throw new Error('The scenario has not specified a badge to render.');
  }

  return scenario;
}

Given(
  'a badge for a passed review with the tone {string}',
  function (this: object, tone: string) {
    scenarios.set(this, { badge: { status: 'passed', tone: toneFrom(tone) } });
  },
);

Given('a badge for a failed review with no tone', function (this: object) {
  scenarios.set(this, { badge: { status: 'failed' } });
});

When('the badge is rendered', function (this: object) {
  const scenario = scenarioFor(this);

  scenario.markup = renderToStaticMarkup(<StatusBadge {...scenario.badge} />);
});

Then('its markup carries the tone {string}', function (this: object, tone: string) {
  const markup = scenarioFor(this).markup;

  assert.ok(markup, 'The badge has not been rendered.');
  assert.match(markup, new RegExp(`(?:^|\\s)data-tone="${tone}"(?:\\s|>)`));
});

Then('it still reads {string}', function (this: object, label: string) {
  const markup = scenarioFor(this).markup;

  assert.ok(markup, 'The badge has not been rendered.');
  assert.ok(markup.includes(`>${label}</span>`), `The badge did not read ${label}.`);
});
"}

